import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Retangulo } from './solution.mjs';

test('cria um retângulo com largura e altura', () => {
  const retangulo = new Retangulo(5, 3);
  assert.equal(retangulo instanceof Retangulo, true);
  assert.equal(retangulo.largura, 5);
  assert.equal(retangulo.altura, 3);
});

test('aceita largura e altura zero', () => {
  const retangulo = new Retangulo(0, 0);
  assert.equal(retangulo.largura, 0);
  assert.equal(retangulo.altura, 0);
});

test('recusa valores que não são números', () => {
  assert.throws(() => new Retangulo('5', 3));
  assert.throws(() => new Retangulo(5, '3'));
});

test('instâncias são independentes entre si', () => {
  const primeiro = new Retangulo(5, 3);
  const segundo = new Retangulo(5, 3);
  primeiro.largura = 99;
  assert.equal(segundo.largura, 5);
});

solutionCode:
// O molde do retângulo: mesma planta, casas independentes.
export class Retangulo {
  constructor(largura, altura) {
    // Portaria de entrada: largura e altura precisam ser números.
    if (typeof largura !== 'number' || typeof altura !== 'number') {
      throw new Error('largura e altura precisam ser números');
    }
    this.largura = largura;
    this.altura = altura;
  }
}
